import sys,json
raw=sys.stdin.read()
i=raw.index('{')
d=json.loads(raw[i:])
def walk(n,depth=0):
    yield n,depth
    for c in n.get('children',[]) or []:
        yield from walk(c,depth+1)
items=d['items']
for it in items:
    for n,dep in walk(it):
        if n['id'].endswith('.u2') or 'u2' in n['id'].split('.')[-1]:
            print(json.dumps(n,indent=2)[:8000])
            print('---')
